input.old_string:
function trim(s) {
  return s.trim();
}

module.exports = { trim };

input.new_string:
function trim(s) {
  return s.trim();
}

function truncate(str, n) {
  if (str.length <= n) return str;
  return str.slice(0, Math.max(0, n)) + '…';
}

module.exports = { trim, truncate };

